# owner: platform
"""Contact sheet rows for substitute teachers."""

from typing import List

from rosterkit.models import Student
from rosterkit.errors import ProjectError


def _require_email(student: Student) -> str:
    if not student.email:
        raise ProjectError(f"no email for {student.display_name}")
    return student.email


def _join(cells, widths) -> str:
    padded = (text.ljust(width) for text, width in zip(cells, widths))
    return "  ".join(padded).rstrip()


def contact_rows(students: List[Student]) -> List[str]:
    """Rows of name, section and email, sorted by name and aligned."""
    if not students:
        raise ProjectError("no students to list")
    ordered = sorted(students, key=lambda item: item.display_name.casefold())
    cells = [(item.display_name, item.section, _require_email(item)) for item in ordered]
    widths = [max(len(cell[index]) for cell in cells) for index in range(3)]
    return [_join(cell, widths) for cell in cells]

after.tests/test_contacts.py:
# owner: platform
import unittest

from rosterkit.models import Student
from rosterkit.errors import ProjectError
from rosterkit.contacts import contact_rows


def _student(last, first, section, email):
    return Student("id", last, first, section, email)


class ContactRowsTests(unittest.TestCase):
    def test_sorted_and_aligned(self):
        rows = contact_rows([
            _student("Young", "Zed", "B", "z@x.org"),
            _student("Abbott", "Amy", "A", "amy@x.org")
        ])
        self.assertEqual(rows, [
            "Abbott, Amy  A  amy@x.org",
            "Young, Zed   B  z@x.org"
        ])

    def test_missing_email_names_student(self):
        with self.assertRaisesRegex(ProjectError, "Young, Zed"):
            contact_rows([_student("Young", "Zed", "B", None)])

    def test_empty_list(self):
        with self.assertRaises(ProjectError):
            contact_rows([])


if __name__ == "__main__":
    unittest.main()
